  // inside the impostor quad (its outer top corner must stay under x = 0.75 there).
  if (aFlag >= 0.0) P.armR = clamp(P.armR * 0.55, -0.3, 0.35);

  P.yaw = atan(fwd.x, fwd.y) + yawSpin;
